 @After public void cleanup()throws Exception{if(f!=null)f.close();}
 JSONObject item(String id,String title,int season,int episode,boolean movie)throws Exception{return f.data.rememberPhoneItem(new JSONObject().put("id",id).put("title",title).put("group",movie?"movie:"+id:"show:"+title).put("movie",movie).put("season",season).put("episode",episode).put("airsAt","2020-01-01T00:00:00Z"));}
 JSONObject saved(String id,String title,int season,int episode,int bytes,boolean watched)throws Exception{JSONObject i=item(id,title,season,episode,false);store.enqueue(i);Files.write(store.file(id,false).toPath(),new byte[bytes]);f.data.localFile(id,android.net.Uri.fromFile(store.file(id,false)).toString());store.update(id,"complete",bytes,bytes,"","");if(watched)f.data.mark(id,true,System.currentTimeMillis()-10L*86400000,false);return f.data.item(id);}
 PhoneDownloadsManage.Group group(String name){return manage.groups("Name").stream().filter(g->g.name.equals(name)).findFirst().get();}
 View tag(View root,String tag){return AuditPhoneFixture.find(root,v->tag.equals(v.getTag()));}
 @Test public void groupingUsesShowThenSeasonAndMoviesWithActualSizesAndSort()throws Exception{
  saved("a1","Alpha",1,1,100,true);saved("a2","Alpha",2,1,200,false);Thread.sleep(2);saved("z","Zulu",1,1,50,false);Thread.sleep(2);JSONObject m=item("movie","Movie",0,0,true);store.enqueue(m);Files.write(store.file("movie",false).toPath(),new byte[25]);store.update("movie","complete",25,25,"","");
  assertEquals(3,manage.groups("Name").size());assertEquals("Alpha",manage.groups("Name").get(0).name);assertEquals(300,group("Alpha").bytes());assertEquals(1,group("Alpha").watched());assertEquals(2,group("Alpha").seasons().size());assertEquals("Alpha",manage.groups("Size").get(0).name);assertEquals("Movies",manage.groups("Recent").get(0).name);assertEquals(25,group("Movies").bytes());
 }
