  saved("s1","Show",1,1,50,true);saved("s2","Show",1,2,75,false);saved("s3","Show",2,1,100,true);saved("s4","Show",2,2,125,false);saved("other","Other",1,1,30,false);String history=f.data.item("s1").optJSONArray("viewings").toString();File side=new File(store.directory,store.file("s1",false).getName().replace(".video",".en.srt"));Files.write(side.toPath(),new byte[5]);
