 @Test public void freeSpaceDeletesOnlyFailedOrOrphanPartsAndOrphanTorrentFolders()throws Exception{
  JSONObject fail=item("failed","Failed",1,1,false),live=item("paused","Paused",1,1,false);store.enqueue(fail);store.update("failed","failed",20,100,"","");Files.write(store.file("failed",true).toPath(),new byte[20]);store.enqueue(live);store.pause("paused");Files.write(store.file("paused",true).toPath(),new byte[30]);File orphan=new File(store.directory,"orphan.part");Files.write(orphan.toPath(),new byte[40]);File dir=new File(store.directory,".torrents/orphan");assertTrue(dir.mkdirs());Files.write(new File(dir,"partial").toPath(),new byte[60]);File unrelated=new File(store.directory,"keep.txt");Files.write(unrelated.toPath(),new byte[90]);
  PhoneDownloadsManage.Suggestion left=manage.suggestions(System.currentTimeMillis()).get(2);assertEquals(120,left.bytes());assertEquals(120,manage.free(List.of(left)));assertFalse(orphan.exists());assertFalse(dir.exists());assertTrue(store.file("paused",true).exists());assertTrue(unrelated.exists());assertNotNull(store.job("failed"));
 }
