 @Test public void moveCopiesSidecarsUpdatesLocalFilePreservesReadyOwnershipAndDefaultVolume()throws Exception{
  File primary=f.data.context.getExternalFilesDir(null),sd=new File(f.root,"sd");assertTrue("move#1",sd.mkdirs());Context context=new ContextWrapper(f.data.context){@Override public Context getApplicationContext(){return this;}@Override public File[] getExternalFilesDirs(String type){return new File[]{primary,sd};}};store=new DownloadStore(context);NoirApp.downloads=store;manage=new PhoneDownloadsManage(f.data,store);JSONObject i=item("move","Move",1,1,false);assertTrue("move#2",store.enqueueReady(i,null,64));File original=store.file("move",false);Files.write(original.toPath(),new byte[64]);store.update("move","complete",64,64,"","");f.data.localFile("move",android.net.Uri.fromFile(original).toString());File side=new File(original.getParentFile(),original.getName().replace(".video",".ar.srt"));Files.write(side.toPath(),new byte[8]);assertTrue("move#3",store.ownsReadyFile(store.job("move")));File destination=new File(sd,"offline");List<Long> progress=new ArrayList<>();store.relocate("move",destination,progress::add);assertFalse("move#4",original.exists());assertFalse("move#5",side.exists());assertEquals("move#6",destination,store.file("move",false).getParentFile());assertEquals("move#7",64,store.file("move",false).length());assertEquals("move#8",android.net.Uri.fromFile(store.file("move",false)).toString(),f.data.localFile("move"));assertEquals("move#9",Long.valueOf(72),progress.get(progress.size()-1));assertTrue("move#10",store.ownsReadyFile(store.job("move")));DownloadStore reopened=new DownloadStore(context);assertEquals("move#11",destination,reopened.file("move",false).getParentFile());store.defaultDirectory(destination);JSONObject n=item("new","Move",1,2,false);store.enqueue(n);assertEquals("move#12",destination,store.file("new",true).getParentFile());store.relocate("move",primary.toPath().resolve("offline").toFile());assertFalse("move#13",new File(destination,original.getName()).exists());assertEquals("move#14",original,store.file("move",false));
 }
