 @Test public void nextNCountsAfterSavedQueuedFutureAndWatchedAcrossSeasons()throws Exception{List<JSONObject> all=new ArrayList<>();for(int s=1;s<=3;s++)for(int e=1;e<=3;e++)all.add(new JSONObject().put("id",s+"-"+e).put("season",s).put("episode",e));DataStore.put(all.get(1),"progress",new JSONObject().put("completed",true));DataStore.put(all.get(4),"airsAt","2099-01-01T00:00:00Z");PhoneSeasonPlan.Options o=new PhoneSeasonPlan.Options();o.scope="Next N episodes";o.next=3;o.skipWatched=true;List<JSONObject> selected=PhoneSeasonPlan.select(all,2,1,o,Set.of("1-3"),Set.of("2-1"),System.currentTimeMillis());assertEquals(List.of("2-3","3-1","3-2"),selected.stream().map(e->e.optString("id")).collect(java.util.stream.Collectors.toList()));}
 @Test public void wholeShowIncludesAiredSeasonsAndOptionalSpecialsAndCapStopsAtFirstOverage()throws Exception{List<JSONObject> all=List.of(new JSONObject("{id:'special',season:0,episode:1}"),new JSONObject("{id:'one',season:1,episode:1}"),new JSONObject("{id:'two',season:2,episode:1}"),new JSONObject("{id:'future',season:3,episode:1,airsAt:'2099-01-01T00:00:00Z'}"));PhoneSeasonPlan.Options o=new PhoneSeasonPlan.Options();o.scope="Whole show";assertEquals(2,PhoneSeasonPlan.select(all,1,1,o,Set.of(),Set.of(),System.currentTimeMillis()).size());o.specials=true;assertEquals(3,PhoneSeasonPlan.select(all,1,1,o,Set.of(),Set.of(),System.currentTimeMillis()).size());assertArrayEquals(new boolean[]{false,true,true},PhoneSeasonPlan.cap(List.of(50L,80L,1L),0,100));assertArrayEquals(new boolean[]{false,false,true},PhoneSeasonPlan.cap(List.of(0L,20L,1L),80,100));assertArrayEquals(new boolean[]{false,false,false},PhoneSeasonPlan.cap(List.of(50L,80L,1L),0,0));JSONObject payload=o.payload(1);assertEquals("Whole show",payload.optString("scope"));assertTrue(payload.optBoolean("includeSpecials"));assertTrue(payload.optBoolean("onlyMissing"));assertTrue(payload.has("releaseIds")==false);}
 @Test public void scopeSheetHasFourCardsBoundedStepperAndFindReleasesOpensReview()throws Exception{JSONObject i=item("sheet","Sheet",1,1,false);PhoneDownloadsActivity a=f.launch(new Intent(f.real,PhoneDownloadsActivity.class).putExtra("id",i.optString("id")));f.ui(()->{NoirSheet s=a.scopeSheet;assertNotNull(tag(s.root,"scope-cards:0"));assertNotNull(tag(s.root,"scope-cards:1"));assertEquals(2,((ViewGroup)tag(s.root,"scope-cards:0")).getChildCount());assertEquals(2,((ViewGroup)tag(s.root,"scope-cards:1")).getChildCount());a.options.next=25;a.step(1);assertEquals(25,a.options.next);a.options.next=1;a.step(-1);assertEquals(1,a.options.next);assertEquals("Next N episodes",a.options.scope);a.options.scope="This episode";a.showForm();AuditPhoneFixture.click(a.scopeSheet.root,"Find releases");});f.until(()->a.total!=null);f.ui(()->{assertEquals(1,a.rows.size());assertNotNull(AuditPhoneFixture.find(a.body,v->v instanceof TextView&&((TextView)v).getText().toString().equals("Download")));});}
 @Test public void arabicSavedHubMirrorsCollapsesMultipleShowsAndRemembersSort()throws Exception{saved("ar1","Alpha",2,1,100,true);saved("ar2","Beta",1,1,200,false);Loc.arabic=true;f.data.pref("language","ar");f.data.pref("downloadsSort","Size");DownloadHubActivity a=f.launch(DownloadHubActivity.class);f.ui(()->{assertEquals(View.LAYOUT_DIRECTION_RTL,a.getWindow().getDecorView().getLayoutDirection());assertEquals("Size",a.list.sort);View group=tag(a.body,"saved-group:show:Alpha");assertNotNull(group);assertTrue(group.getContentDescription().toString().contains("100"));assertFalse(group.getContentDescription().toString().contains("episodes"));View row=tag(a.body,"job-row:ar1");assertFalse(row.isShown());group.performClick();assertTrue(tag(a.body,"job-row:ar1").isShown());TextView episode=(TextView)tag(tag(a.body,"job-row:ar1"),"episode");assertEquals(View.TEXT_DIRECTION_LTR,episode.getTextDirection());assertNotNull(tag(a.body,"saved-sort"));});}
 @Test public void remoteDeleteCapabilitySendsOnlyJobIdAndAcceptsResultThenRefreshes()throws Exception{List<JSONObject> sent=new java.util.concurrent.CopyOnWriteArrayList<>();f.data.fetchOverride=(path,body)->{if(path.equals("/v1/pc-downloads/delete")){sent.add(DataStore.copy(body));return new JSONObject("{ok:true,files:1,bytes:100}");}return new JSONObject("{configured:true,capabilities:{deleteFinished:true},jobs:"+(sent.isEmpty()?"[{id:'done',name:'Finished',status:'Completed',size:100,bytes:100}]":"[]")+"}");};PcDownloadsActivity a=f.launch(PcDownloadsActivity.class);f.until(()->a.queueStates.containsKey("done"));f.ui(()->{assertTrue(a.supportsDelete);AuditPhoneFixture.click(a.queueActions.get("done"),"Delete");});f.ui(()->{View sheet=null;for(View root:android.view.inspector.WindowInspector.getGlobalWindowViews()){View candidate=tag(root,"noir-sheet");if(candidate!=null&&candidate.isShown())sheet=candidate;}assertNotNull(sheet);assertNotNull(AuditPhoneFixture.find(sheet,v->v instanceof TextView&&((TextView)v).getText().toString().equals(Loc.t("Your PC will ask you to confirm deletion."))));AuditPhoneFixture.click(sheet,"Delete");});f.until(()->!sent.isEmpty()&&!a.queueStates.containsKey("done"));assertEquals(1,sent.size());assertEquals(1,sent.get(0).length());assertEquals("done",sent.get(0).getString("id"));}
 @Test public void remoteDeleteIsHiddenWithoutCapabilityAndScopeFieldsKeepReleaseIdsCompatibility()throws Exception{JSONObject i=item("pc","PC",1,1,false);List<JSONObject> plans=new ArrayList<>();f.data.fetchOverride=(path,body)->{if(path.contains("/search/"))return new JSONObject("{choices:[{id:'release'}]}");if(path.contains("/plan/")){plans.add(DataStore.copy(body));return new JSONObject("{entries:[],episodes:[]}");}return new JSONObject("{configured:true,jobs:[{id:'done',name:'Finished',status:'Completed',size:100,bytes:100}]}");};PhoneSeasonPlan.Options o=new PhoneSeasonPlan.Options();o.scope="Whole show";o.maxTotal=123;PcDownloadsActivity a=f.launch(new Intent(f.real,PcDownloadsActivity.class).putExtra("id",i.optString("id")).putExtra("season",true).putExtra("scopeRequest",o.payload(1).toString()));f.until(()->!plans.isEmpty()&&a.files!=null);assertEquals("Whole show",plans.get(0).optString("scope"));assertEquals(123,plans.get(0).optLong("maxTotalBytes"));assertEquals(0,plans.get(0).optJSONArray("releaseIds").length());JSONArray manual=new JSONArray().put(new JSONObject().put("id","release"));f.ui(()->{a.manualReleases=true;a.loadPlan(manual);});f.until(()->plans.size()==2&&!a.busy);assertEquals("release",plans.get(1).optJSONArray("releaseIds").optString(0));f.ui(()->{a.itemId="";a.queue();});f.until(()->a.queueStates.containsKey("done"));f.ui(()->{assertFalse(a.supportsDelete);assertEquals(0,a.queueActions.get("done").getChildCount());});}
